{
    Thing sword = { true, false, 0 };
    Thing bow = { false, false, 3 };
    Carrying c = { false, &sword, 0, -1, 0, 0 };
    PerformAction(&c, &bow);
    if (c.dropped != 1 || c.primary != 0 || c.slotThing != &bow || c.slot != 3 || g_refreshed != 1 || !g_aggressive) {
        std::printf("0069f9e0_TEST FAIL\n"); return 1;
