    if (g.put != 0) { std::printf("0078e9c0_TEST FAIL\n"); return 1; }
    item.dead = false;
    tc.UnsheatheWeapon();
    if (g.drops != 1 || g.reacts != 1 || g.clearPrimary != 1 || g.put != 1 || g.putSlot != 3 || g.putThing != &item
        || g.refresh != 1 || g.flourishOff != 1 || g.restart != 1 || g.aggressive != 1) { std::printf("0078e9c0_TEST FAIL\n"); return 1; }
    std::printf("0078e9c0_TEST PASS\n");
    return 0;
}

